package com.revivex.engine; import com.revivex.domain.PaymentEvent; import org.springframework.stereotype.Component; import java.util.*; @Component public class InterventionOptimizer { public Decision optimize(PaymentEvent p,String cause,double probability){List<Candidate> cs=List.of(new Candidate("SMART_RETRY",probability+(cause.equals("TRANSIENT_BANK_ERROR")?.12:0),.35,.05),new Candidate("PAYMENT_NUDGE",probability*.88+(cause.equals("CUSTOMER_ACTION_REQUIRED")?.12:0),.10,.03),new Candidate("CHECKOUT_RECOVERY",probability*.84+(cause.equals("CHECKOUT_ABANDONMENT")?.18:0),.08,.02),new Candidate("SUBSCRIPTION_RETRY",probability*.90+(cause.equals("SUBSCRIPTION_PAYMENT_FAILURE")?.14:0),.20,.03),new Candidate("MANDATE_RETRY",probability*.86+(cause.equals("MANDATE_DEGRADATION")?.16:0),.18,.03),new Candidate("B2B_CHASER",probability*.92+(cause.equals("OVERDUE_RECEIVABLE")?.15:0),.25,.02),new Candidate("STOP",.02,0,.00));Candidate best=cs.stream().max(Comparator.comparingDouble(c->c.value(p.getAmount()))).orElse(cs.get(cs.size()-1));if(cause.equals("NON_RETRYABLE")||p.isHighRisk())best=cs.get(cs.size()-1);return new Decision(best.action(),Math.min(.99,Math.max(.01,best.probability())),best.cost(),best.friction());} record Candidate(String action,double probability,double cost,double friction){double value(java.math.BigDecimal amount){return probability-cost/Math.max(10000.0,amount.doubleValue())-friction;}} public record Decision(String action,double probability,double cost,double friction){} }
